export interface Post {
  id: string
  title: string
  content: string
}

let posts: Post[] = [
  {
    id: '1',
    title: 'Hello world',
    content: 'This is the first post.',
  },
]

function getAllPosts(): Post[] {
  return posts
}

export function addPost(title: string, content: string): Post {
  const post: Post = {
    id: String(Date.now()),
