'use server'

import { updateTag } from 'next/cache'
import { addPost } from '@/lib/posts'

export async function createPost(formData: FormData): Promise<void> {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title || !content) {
    throw new Error('Title and content are required')
  }

  addPost(title, content)

  // updateTag (not revalidateTag) fully invalidates the "posts" tag AND
  // refreshes the client router cache, blocking subsequent reads until fresh
  // data is fetched, so no stale cached content is served on the next load.
  updateTag('posts')
}

